function AutomationCard({ item, status, onRun, onUpload, fileName }) {
  const Icon = ICONS_MAP[item.icon];
  return (
    <div className="sage-card" style={{ display:'flex', flexDirection:'column', gap:12 }}>
      <div style={{ display:'flex', alignItems:'center', gap:10 }}>
        <div style={{ width:38, height:38, borderRadius:10, background:'var(--sage-mist)', display:'flex', alignItems:'center', justifyContent:'center', color:'var(--sage-green)', flexShrink:0 }}>
          <Icon size={18} />
        </div>
        <div style={{ fontWeight:700, fontSize:14.5 }}>{item.title}</div>
      </div>
      <div style={{ fontSize:13, color:'var(--ink-soft)', flex:1 }}>{item.desc}</div>

      {item.upload && status !== 'synced' && (
        <label className="sage-btn sage-btn-outline sage-btn-sm" style={{ width:'fit-content' }}>
          <Upload size={13} /> {fileName || 'Choose file (.csv/.xlsx)'}
          <input type="file" accept=".csv,.xlsx,.xls" style={{ display:'none' }} onChange={e => onUpload(e.target.files && e.target.files[0] ? e.target.files[0].name : null)} />
        </label>
      )}

      <div style={{ display:'flex', alignItems:'center', gap:10, marginTop:4 }}>
        {status === 'idle' && (
          <button className="sage-btn sage-btn-primary sage-btn-sm" disabled={item.upload && !fileName} onClick={onRun}>
            <Zap size={13} /> Run
          </button>
        )}
        {status === 'running' && (
          <span className="sage-pill pill-gold"><Loader2 size={13} className="sage-spin" /> Running…</span>
        )}
        {status === 'synced' && (
          <span className="sage-pill pill-success"><CheckCircle2 size={13} /> Synced just now</span>
        )}
      </div>
    </div>
  );
}

function AutomationControlCenter() {
  const [statuses, setStatuses] = useState({});
  const [files, setFiles] = useState({});

  const runAutomation = (id) => {
    setStatuses(s => ({ ...s, [id]: 'running' }));
    setTimeout(() => setStatuses(s => ({ ...s, [id]: 'synced' })), 2000 + Math.random()*800);
  };

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:20 }}>
      <div className="font-display" style={{ fontSize:24 }}>Automation Control Center</div>
      <div className="sage-card-tight" style={{ fontSize:13, color:'var(--ink-soft)', display:'flex', gap:10, alignItems:'flex-start' }}>
        <Info size={16} color="var(--sage-green)" style={{ flexShrink:0, marginTop:1 }} />
        <span>Every workflow below runs on data your school exports or enters directly into SAGE — never by logging into another vendor's ERP portal on your behalf.</span>
      </div>
      <KarmaFormulaCard />
      <div className="sage-grid-4">
        {AUTOMATIONS.map(item => (
          <AutomationCard key={item.id} item={item} status={statuses[item.id] || 'idle'}
            fileName={files[item.id]}
            onUpload={(name) => name && setFiles(f => ({ ...f, [item.id]: name }))}
            onRun={() => runAutomation(item.id)} />
        ))}
      </div>
    </div>
  );
}

